// Birds glossary (Hebrew): a page per common bird of Israel, per record-holding bird of the world and per key term,
// each linked to the lesson that teaches it. Birds that already have a page elsewhere — /animals/* (hoopoe, barn owl,
// golden eagle, flamingo, ostrich, chicken, budgerigar, emperor penguin) and /learn/animals/concepts/* (peregrine
// falcon, common crane, Palestine sunbird, griffon vulture, bird of prey) — are linked from the lessons, not repeated.
// Numbers checked against two sources (2026-10-30), approximate where they differ. Safety: never touch nests, eggs,
// chicks or injured birds; an adult calls רשות הטבע והגנים.
const q = (question, right, wrong, exp) => ({ q: question, options: [right, ...wrong], exp })
// kind 'term' → "מה זה …?"; kind 'bird' → "… — עובדות לילדים".
const concept = ({ kind = 'bird', ...c }) => ({
  title: kind === 'term' ? `מה זה ${c.term}?` : `${c.term}: עובדות לילדים`,
  seoTitle: kind === 'term' ? `מה זה ${c.term}? הסבר פשוט לילדים, דוגמאות וחידון` : `${c.term} — עובדות על הציפור לילדים, זיהוי וחידון`,
  // The short definition plus a note, trimmed to what fits a search snippet (≤ 168 characters).
  seoDesc: c.seoDesc || [`${c.short} הסבר לילדים עם דוגמאות וחידון.`, `${c.short} עם חידון.`, c.short].find(s => s.length <= 168),
  ...c
})

